#include "kernel_operator.h"

struct AdvanceStepTiling {
    int64_t numSeqs;
    int64_t numQueries;
    int64_t blockSize;
    int64_t maxBlocksPerSeq;
    int64_t tileLength;
    int64_t totalTiles;
    int64_t tilesPerCore;
    int64_t coreTileLength;
};

template <typename T>
__aicore__ inline void CopyTilingLocal(T *tiling, GM_ADDR tilingGM)
{
    auto *dst = reinterpret_cast<int32_t *>(tiling);
    auto *src = reinterpret_cast<__gm__ int32_t *>(tilingGM);
    for (size_t i = 0; i < sizeof(T) / sizeof(int32_t); ++i) {
        dst[i] = src[i];
    }
}

class KernelAdvanceStepFlashAttn {
public:
    __aicore__ inline void Init(
        GM_ADDR input_tokens,
        GM_ADDR sampled_token_ids,
        GM_ADDR input_positions,
        GM_ADDR seq_lens,
        GM_ADDR slot_mapping,
        GM_ADDR block_tables,
        GM_ADDR tilingGM,
        AscendC::TPipe *pipe)
    {
        CopyTilingLocal(&tiling_, tilingGM);

        inputTokensGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int64_t *>(input_tokens),
                                        tiling_.numSeqs);
        sampledTokenIdsGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int64_t *>(sampled_token_ids),
                                            tiling_.numQueries);
        inputPositionsGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int64_t *>(input_positions),
                                           tiling_.numSeqs);
        seqLensGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int64_t *>(seq_lens),
                                    tiling_.numSeqs);
        slotMappingGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int64_t *>(slot_mapping),
                                        tiling_.numSeqs);
        blockTablesGm_.SetGlobalBuffer(reinterpret_cast<__gm__ int64_t *>(block_tables),
                                        tiling_.numSeqs * tiling_.maxBlocksPerSeq);

        pipe_ = pipe;

        uint32_t tileBytes = static_cast<uint32_t>(tiling_.tileLength * sizeof(int64_t));
        uint32_t alignedBytes = ((tileBytes + 31U) / 32U) * 32U;

        pipe_->InitBuffer(inQueueSampled_, 2, alignedBytes);
        pipe_->InitBuffer(inQueueSeq_, 2, alignedBytes);
        pipe_->InitBuffer(outQueueTokens_, 2, alignedBytes);
        pipe_->InitBuffer(outQueueSeq_, 2, alignedBytes);
        pipe_->InitBuffer(outQueuePos_, 2, alignedBytes);
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            int64_t coreIdx = static_cast<int64_t>(AscendC::GetBlockIdx());
            for (int64_t localIdx = 0; localIdx < tiling_.tilesPerCore; ++localIdx) {
                int64_t globalTileIdx = coreIdx * tiling_.tilesPerCore + localIdx;
                if (globalTileIdx >= tiling_.totalTiles) {
                    break;
                }
                int64_t queryBase = globalTileIdx * tiling_.tileLength;
                int64_t curTile = tiling_.tileLength;
                if (queryBase + curTile > tiling_.numQueries) {
                    curTile = tiling_.numQueries - queryBase;
                }
                if (curTile <= 0) {
                    break;
                }

                CopyIn(globalTileIdx, queryBase, curTile);
                Compute(globalTileIdx, queryBase, curTile);
                CopyOut(globalTileIdx, queryBase, curTile);
            }
        }
    }

private:
    __aicore__ inline void CopyIn(int64_t /*tileIdx*/, int64_t queryBase, int64_t curTile)
    {
        inQueueSampled_.AllocTensor<int64_t>(sampledLocal_);
        inQueueSeq_.AllocTensor<int64_t>(seqLocal_);

        uint32_t copyBytes = static_cast<uint32_t>(curTile * sizeof(int64_t));
        AscendC::DataCopyExtParams copyParams{1, copyBytes, 0, 0, 0};
        AscendC::DataCopyPadExtParams<int64_t> padParams{false, 0, 0, 0};

        // sampled_token_ids has shape [num_queries, 1]; element [i, 0] is at 1D offset i
        AscendC::DataCopyPad(sampledLocal_, sampledTokenIdsGm_[queryBase], copyParams, padParams);
        inQueueSampled_.EnQue(sampledLocal_);

        AscendC::DataCopyPad(seqLocal_, seqLensGm_[queryBase], copyParams, padParams);
        inQueueSeq_.EnQue(seqLocal_);
    }

    __aicore__ inline void Compute(int64_t /*tileIdx*/, int64_t queryBase, int64_t curTile)
    {
        inQueueSampled_.DeQue<int64_t>(sampledLocal_);
        inQueueSeq_.DeQue<int64_t>(seqLocal_);

        outQueueTokens_.AllocTensor<int64_t>(tokensLocal_);
        outQueueSeq_.AllocTensor<int64_t>(seqOutLocal_);
        outQueuePos_.AllocTensor<int64_t>(posLocal_);

        uint32_t curTileU32 = static_cast<uint32_t>(curTile);

        // Step 1: input_tokens = squeeze(sampled_token_ids)
        AscendC::Duplicate(tokensLocal_, static_cast<int64_t>(0), curTileU32);
        AscendC::Add(tokensLocal_, sampledLocal_, tokensLocal_, curTileU32);
        outQueueTokens_.EnQue(tokensLocal_);

        // Step 2: seq_lens += 1
        // Use a temp computed on Vector side
        AscendC::Adds(seqOutLocal_, seqLocal_, static_cast<int64_t>(1), curTileU32);

        // Step 3: input_positions = seq_lens - 1
        AscendC::Adds(posLocal_, seqOutLocal_, static_cast<int64_t>(-1), curTileU32);
        outQueuePos_.EnQue(posLocal_);
        outQueueSeq_.EnQue(seqOutLocal_);

        // Step 4: slot_mapping per-element lookup from block_tables
        // Uses scalar operations due to per-element random access into block_tables
        for (int64_t i = 0; i < curTile; ++i) {
            int64_t seqLen = seqOutLocal_.GetValue(static_cast<int32_t>(i));
            int64_t seqMinus1 = seqLen - 1;
            int64_t blockIdx = seqMinus1 / tiling_.blockSize;
            int64_t blockOffset = seqMinus1 % tiling_.blockSize;

            if (blockIdx < tiling_.maxBlocksPerSeq) {
                int64_t queryIdx = queryBase + i;
                int64_t physBlock = blockTablesGm_.GetValue(
                    queryIdx * tiling_.maxBlocksPerSeq + blockIdx);
                int64_t slotVal = physBlock * tiling_.blockSize + blockOffset;
                slotMappingGm_.SetValue(queryIdx, slotVal);
            }
        }

        inQueueSampled_.FreeTensor(sampledLocal_);
        inQueueSeq_.FreeTensor(seqLocal_);
    }

    __aicore__ inline void CopyOut(int64_t /*tileIdx*/, int64_t queryBase, int64_t curTile)
    {
        outQueueTokens_.DeQue<int64_t>(tokensLocal_);
        outQueueSeq_.DeQue<int64_t>(seqOutLocal_);
        outQueuePos_.DeQue<int64_t>(posLocal_);

        uint32_t copyBytes = static_cast<uint32_t>(curTile * sizeof(int64_t));
        AscendC::DataCopyExtParams copyOutParams{1, copyBytes, 0, 0, 0};

        AscendC::DataCopyPad(inputTokensGm_[queryBase], tokensLocal_, copyOutParams);
        outQueueTokens_.FreeTensor(tokensLocal_);

        AscendC::DataCopyPad(seqLensGm_[queryBase], seqOutLocal_, copyOutParams);
        outQueueSeq_.FreeTensor(seqOutLocal_);

        AscendC::DataCopyPad(inputPositionsGm_[queryBase], posLocal_, copyOutParams);
        outQueuePos_.FreeTensor(posLocal_);
    }

private:
    AdvanceStepTiling tiling_{};
    AscendC::TPipe *pipe_{nullptr};

    AscendC::GlobalTensor<int64_t> inputTokensGm_;
    AscendC::GlobalTensor<int64_t> sampledTokenIdsGm_;
    AscendC::GlobalTensor<int64_t> inputPositionsGm_;
    AscendC::GlobalTensor<int64_t> seqLensGm_;
    AscendC::GlobalTensor<int64_t> slotMappingGm_;
    AscendC::GlobalTensor<int64_t> blockTablesGm_;

    AscendC::TQue<AscendC::TPosition::VECIN, 1> inQueueSampled_;
    AscendC::TQue<AscendC::TPosition::VECIN, 1> inQueueSeq_;
    AscendC::TQue<AscendC::TPosition::VECOUT, 1> outQueueTokens_;
    AscendC::TQue<AscendC::TPosition::VECOUT, 1> outQueueSeq_;
    AscendC::TQue<AscendC::TPosition::VECOUT, 1> outQueuePos_;

    AscendC::LocalTensor<int64_t> sampledLocal_;
    AscendC::LocalTensor<int64_t> seqLocal_;
    AscendC::LocalTensor<int64_t> tokensLocal_;
    AscendC::LocalTensor<int64_t> seqOutLocal_;
    AscendC::LocalTensor<int64_t> posLocal_;
};

extern "C" __global__ __aicore__ void npu_advance_step_flashattn_kernel(
    GM_ADDR input_tokens,
    GM_ADDR sampled_token_ids,
    GM_ADDR input_positions,
    GM_ADDR seq_lens,
    GM_ADDR slot_mapping,
    GM_ADDR block_tables,
    GM_ADDR tiling)
{
    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIC_1_1);
    AscendC::TPipe pipe;
    KernelAdvanceStepFlashAttn kernel;
    kernel.Init(input_tokens, sampled_token_ids, input_positions,
                seq_lens, slot_mapping, block_tables, tiling, &pipe);
    kernel.Process();
}
