#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_npu_advance_step_flashattn_kernel.h"

#include <cstring>

struct AdvanceStepTiling {
    int64_t numSeqs;
    int64_t numQueries;
    int64_t blockSize;
    int64_t maxBlocksPerSeq;
    int64_t tileLength;
    int64_t totalTiles;
    int64_t tilesPerCore;
    int64_t coreTileLength;
};

static int64_t CeilDivI64(int64_t a, int64_t b)
{
    if (b == 0) { return 0; }
    return (a + b - 1) / b;
}

namespace ascend_kernel {

void npu_advance_step_flashattn(
    at::Tensor &input_tokens,
    const at::Tensor &sampled_token_ids,
    at::Tensor &input_positions,
    at::Tensor &seq_lens,
    at::Tensor &slot_mapping,
    const at::Tensor &block_tables,
    int64_t num_seqs,
    int64_t num_queries,
    int64_t block_size)
{
    TORCH_CHECK(num_seqs > 0, "num_seqs must be > 0");
    TORCH_CHECK(num_queries > 0, "num_queries must be > 0");
    TORCH_CHECK(block_size > 0, "block_size must be > 0");
    TORCH_CHECK(input_tokens.scalar_type() == at::kLong, "input_tokens must be int64");
    TORCH_CHECK(sampled_token_ids.scalar_type() == at::kLong, "sampled_token_ids must be int64");
    TORCH_CHECK(input_positions.scalar_type() == at::kLong, "input_positions must be int64");
    TORCH_CHECK(seq_lens.scalar_type() == at::kLong, "seq_lens must be int64");
    TORCH_CHECK(slot_mapping.scalar_type() == at::kLong, "slot_mapping must be int64");
    TORCH_CHECK(block_tables.scalar_type() == at::kLong, "block_tables must be int64");

    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);

    int64_t maxBlocksPerSeq = block_tables.size(1);

    // Compute tileLength based on UB budget
    // We have 5 TQue (each BUFFER_NUM=2) → 10 buffers total
    // Each buffer = tileLength * sizeof(int64_t) bytes
    // bufferCoefficient = 12 (10 buffers + margin)
    int64_t bufferCoefficient = 12;
    int64_t elemSize = static_cast<int64_t>(sizeof(int64_t));
    int64_t ubBytes = static_cast<int64_t>(ubSize);
    int64_t rawTileLength = ubBytes / (bufferCoefficient * elemSize);
    // 32B aligned: ensure tileLength * sizeof(int64_t) is 32B aligned
    int64_t elemsPer32B = 32 / elemSize;  // 4
    int64_t tileLength = (rawTileLength / elemsPer32B) * elemsPer32B;
    if (tileLength < elemsPer32B) {
        tileLength = elemsPer32B;  // minimum 4 elements
    }
    if (tileLength > 512) {
        tileLength = 512;  // cap for reasonable UB usage
    }

    int64_t totalTiles = CeilDivI64(num_queries, tileLength);
    int64_t usedCoreNum = coreNum;
    if (usedCoreNum > totalTiles) {
        usedCoreNum = totalTiles;
    }
    if (usedCoreNum < 1) {
        usedCoreNum = 1;
    }
    int64_t tilesPerCore = CeilDivI64(totalTiles, usedCoreNum);

    // Build tiling struct
    AdvanceStepTiling tilingHost;
    tilingHost.numSeqs = num_seqs;
    tilingHost.numQueries = num_queries;
    tilingHost.blockSize = block_size;
    tilingHost.maxBlocksPerSeq = maxBlocksPerSeq;
    tilingHost.tileLength = tileLength;
    tilingHost.totalTiles = totalTiles;
    tilingHost.tilesPerCore = tilesPerCore;
    tilingHost.coreTileLength = tileLength;

    // Copy tiling to NPU device memory
    at::Tensor tilingCpu = at::empty(
        {static_cast<int64_t>(sizeof(AdvanceStepTiling))},
        at::device(at::kCPU).dtype(at::kByte));
    std::memcpy(tilingCpu.data_ptr(), &tilingHost, sizeof(AdvanceStepTiling));
    auto tilingNpu = ascend_kernel::TorchNpuHelper::CopyTensorHostToDevice(tilingCpu);

    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
    int64_t l_num_seqs = num_seqs;
    int64_t l_num_queries = num_queries;
    int64_t l_block_size = block_size;

    EXEC_KERNEL_CMD(npu_advance_step_flashattn_kernel, blockDim,
                    input_tokens, sampled_token_ids, input_positions,
                    seq_lens, slot_mapping, block_tables, tilingNpu,
                    l_num_seqs, l_num_queries, l_block_size);
}

}  // namespace ascend_kernel
