template <typename T>
__aicore__ inline void CopyTilingLocal(T *pTiling, GM_ADDR tilingGM)
{
    auto *pDst = reinterpret_cast<int32_t *>(pTiling);
    auto *pSrc = reinterpret_cast<__gm__ int32_t *>(tilingGM);
    for (size_t i = 0; i < sizeof(T) / sizeof(int32_t); ++i) {
